3	enum NinebotServerError: LocalizedError {
4	    case invalidBaseURL
5	    case invalidResponse
6	    case server(String)
7	    case httpStatus(Int, String)
8	
9	    var errorDescription: String? {
10	        switch self {
11	        case .invalidBaseURL:
12	            return "服务器地址无效"
13	        case .invalidResponse:
14	            return "服务器返回的数据格式无效"
15	        case .server(let message):
16	            return message
17	        case .httpStatus(let statusCode, let message):
18	            if message.isEmpty {
19	                return "HTTP \(statusCode)"
20	            }
21	            return "HTTP \(statusCode): \(message)"
22	        }
23	    }
24	}
