80	    func fetchDashboard(selectedSN: String? = nil) async throws -> NinebotDashboard {
81	        let vehiclesPayload = try await request(method: "GET", path: ["vehicles"])
82	        let vehicleValues = Self.arrayPayload(from: vehiclesPayload, preferredKeys: ["vehicles", "data"])
83	        let vehicles = vehicleValues.compactMap(Self.vehicleInfo)
84	        let currentMonth = Self.currentMonthString()
85	
86	        var snapshots: [NinebotVehicleSnapshot] = []
87	        for vehicle in vehicles {
88	            let dashboard: JSONValue?
89	            do {
90	                dashboard = try await request(method: "GET", path: ["vehicles", vehicle.sn, "dashboard"])
91	            } catch {
92	                dashboard = nil
93	            }
94	            let dashboardObject = dashboard?.objectValue
95	            let status: JSONValue?
96	            let travel: JSONValue?
97	            let battery: JSONValue?
98	            let prediction: NinebotServerPrediction?
99	            let stableState = dashboardObject?["state"]
100	            if let stableState, Self.hasVehicleStatus(stableState) {
101	                status = stableState
102	                travel = dashboardObject?["travel"]
103	                battery = Self.hasBatteryData(dashboardObject?["battery"])
104	                    ? dashboardObject?["battery"]
105	                    : stableState
106	                prediction = dashboardObject?["prediction"].flatMap(Self.serverPrediction)
107	            } else if let dashboardObject,
108	               Self.hasVehicleStatus(dashboardObject["status"]),
109	               Self.hasBatteryData(dashboardObject["battery"]) {
110	                status = dashboardObject["status"]
111	                travel = dashboardObject["travel"]
112	                battery = dashboardObject["battery"]
113	                prediction = dashboardObject["prediction"].flatMap(Self.serverPrediction)
114	            } else {
115	                // Status and battery are the authoritative snapshot.  Never turn a
116	                // failed request into an empty, apparently successful dashboard.
117	                let fallbackStatus = try await request(method: "GET", path: ["vehicles", vehicle.sn, "status"])
118	                let fallbackBattery = try await request(method: "GET", path: ["vehicles", vehicle.sn, "battery"])
119	                guard Self.hasVehicleStatus(fallbackStatus) else {
120	                    throw NinebotServerError.server("服务器没有返回车辆状态，请在管理端检查该车辆最近一次轮询")
121	                }
122	                guard Self.hasBatteryData(fallbackBattery) else {
123	                    throw NinebotServerError.server("服务器没有返回电池数据，请在管理端检查该车辆最近一次轮询")
124	                }
125	                status = fallbackStatus
126	                travel = try? await fetchTravel(sn: vehicle.sn, month: currentMonth)
127	                battery = fallbackBattery
128	                prediction = try? await fetchPrediction(sn: vehicle.sn)
129	            }
130	            let monthlyTravels = await fetchMonthlyTravels(
131	                sn: vehicle.sn,
132	                authDate: vehicle.authDate,
133	                currentMonth: currentMonth,
134	                currentTravel: travel
135	            )
136	            var state = Self.vehicleState(
137	                status: status,
138	                travel: travel,
139	                battery: battery,
140	                prediction: prediction,
141	                updatedAt: Self.serverDateValue(dashboardObject?["updated_at"] ?? dashboardObject?["updatedAt"]) ?? Date()
142	            )
143	            if let totalMileage = Self.totalMileage(fromMonthlyTravels: monthlyTravels) {
144	                state.totalMileage = totalMileage
145	            }
146	            let dashboardVehicle = dashboardObject?["vehicle"].flatMap(Self.vehicleInfo) ?? vehicle
147	            let resolvedVehicle = Self.vehicleInfo(dashboardVehicle, addingImageFrom: status, battery: battery)
148	            snapshots.append(NinebotVehicleSnapshot(vehicle: resolvedVehicle, state: state))
149	        }
150	
151	        let resolvedSelectedSN: String?
152	        if let selectedSN, snapshots.contains(where: { $0.vehicle.sn == selectedSN }) {
153	            resolvedSelectedSN = selectedSN
154	        } else {
155	            resolvedSelectedSN = snapshots.first?.vehicle.sn
156	        }
157	
158	        return NinebotDashboard(
159	            vehicles: snapshots,
160	            selectedSN: resolvedSelectedSN,
161	            updatedAt: Date()
162	        )
163	    }
