205	    private func fetchMonthlyTravels(
206	        sn: String,
207	        authDate: Date?,
208	        currentMonth: String,
209	        currentTravel: JSONValue?
210	    ) async -> [JSONValue]? {
211	        let months = Self.monthStrings(from: authDate, through: Date())
212	        guard !months.isEmpty else {
213	            return currentTravel.map { [$0] }
214	        }
215	
216	        var payloads: [JSONValue] = []
217	        for month in months {
218	            if month == currentMonth, let currentTravel {
219	                payloads.append(currentTravel)
220	                continue
221	            }
222	
223	            do {
224	                payloads.append(try await fetchTravel(sn: sn, month: month))
225	            } catch {
226	                return nil
227	            }
228	        }
229	        return payloads
230	    }
