276	    private func request(
277	        method: String,
278	        path: [String],
279	        queryItems: [URLQueryItem] = [],
280	        body: [String: String]? = nil
281	    ) async throws -> JSONValue {
282	        let url = try buildURL(path: path, queryItems: queryItems)
283	        var request = URLRequest(url: url)
284	        request.httpMethod = method
285	        request.timeoutInterval = 20
286	        request.setValue("application/json", forHTTPHeaderField: "Accept")
287	
288	        let token = configuration.bearerToken.trimmingCharacters(in: .whitespacesAndNewlines)
289	        if !token.isEmpty {
290	            request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
291	        }
292	        if let sessionToken = configuration.appSessionToken?.trimmingCharacters(in: .whitespacesAndNewlines),
293	           !sessionToken.isEmpty {
294	            request.setValue(sessionToken, forHTTPHeaderField: "X-NinePlus-Session")
295	        }
296	
297	        if let body {
298	            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
299	            request.httpBody = try JSONEncoder().encode(body)
300	        }
301	
302	        let (data, response) = try await session.data(for: request)
303	        guard let httpResponse = response as? HTTPURLResponse else {
304	            throw NinebotServerError.invalidResponse
305	        }
306	
307	        if !(200..<300).contains(httpResponse.statusCode) {
308	            throw NinebotServerError.httpStatus(httpResponse.statusCode, Self.errorMessage(from: data))
309	        }
310	
311	        if data.isEmpty {
312	            return .object([:])
313	        }
314	
315	        let root = try JSONDecoder().decode(JSONValue.self, from: data)
316	        return try Self.unwrapEnvelope(root)
317	    }
318	
319	    private func buildURL(path: [String], queryItems: [URLQueryItem]) throws -> URL {
320	        guard var url = configuration.baseURL else {
321	            throw NinebotServerError.invalidBaseURL
322	        }
323	
324	        for component in path {
325	            url.appendPathComponent(component)
326	        }
327	
328	        guard !queryItems.isEmpty else { return url }
329	        guard var components = URLComponents(url: url, resolvingAgainstBaseURL: false) else {
330	            throw NinebotServerError.invalidBaseURL
331	        }
332	        components.queryItems = queryItems
333	        guard let finalURL = components.url else {
334	            throw NinebotServerError.invalidBaseURL
335	        }
336	        return finalURL
337	    }
338	}
