340	private extension NinebotServerClient {
341	    static func unwrapEnvelope(_ root: JSONValue) throws -> JSONValue {
342	        guard let object = root.objectValue, object.keys.contains("ok") else {
343	            return root
344	        }
345	
346	        if object["ok"]?.boolValue == true {
347	            return object["data"] ?? .object([:])
348	        }
349	
350	        let error = object["error"]?.objectValue
351	        let message = error?["message"]?.stringValue
352	            ?? error?["code"]?.stringValue
353	            ?? "NinePlus 服务器请求失败"
354	        throw NinebotServerError.server(message)
355	    }
356	
357	    static func errorMessage(from data: Data) -> String {
358	        guard !data.isEmpty else { return "" }
359	        if let root = try? JSONDecoder().decode(JSONValue.self, from: data) {
360	            if let object = root.objectValue {
361	                if let error = object["error"]?.objectValue {
362	                    return error["message"]?.stringValue ?? error["code"]?.stringValue ?? ""
363	                }
364	                return object["message"]?.stringValue ?? ""
365	            }
366	        }
367	        return String(data: data, encoding: .utf8) ?? ""
368	    }
