463	    static func serverPrediction(from value: JSONValue) -> NinebotServerPrediction? {
464	        guard let object = value.objectValue else { return nil }
465	        let range = object["range"]?.objectValue ?? [:]
466	        let charging = object["charging"]?.objectValue ?? [:]
467	        guard !range.isEmpty || !charging.isEmpty else { return nil }
468	
469	        return NinebotServerPrediction(
470	            modelVersion: firstString(["model_version", "modelVersion"], in: object),
471	            updatedAt: serverDateValue(object["updated_at"] ?? object["updatedAt"]),
472	            batteryPercent: firstDouble(["battery_percent", "batteryPercent"], in: object),
473	            batteryChemistry: batteryChemistryInfo(from: object["battery_chemistry"] ?? object["batteryChemistry"]),
474	            range: NinebotServerRangePrediction(
475	                estimatedRange: firstDouble(["estimated_range_km", "estimatedRangeKm"], in: range),
476	                localRange: firstDouble(["local_range_km", "localRangeKm"], in: range),
477	                officialRange: firstDouble(["official_range_km", "officialRangeKm"], in: range),
478	                source: firstString(["source"], in: range),
479	                kmPerPercent: firstDouble(["km_per_percent", "kmPerPercent"], in: range),
480	                estimatedFullRange: firstDouble(["estimated_full_range_km", "estimatedFullRangeKm"], in: range),
481	                sampleCount: range["sample_count"]?.intValue ?? range["sampleCount"]?.intValue,
482	                totalUsedPercent: firstDouble(["total_used_percent", "totalUsedPercent"], in: range),
483	                accuracyPercent: firstDouble(["accuracy_percent", "accuracyPercent"], in: range),
484	                confidencePercent: firstDouble(["confidence_percent", "confidencePercent"], in: range),
485	                accuracySource: firstString(["accuracy_source", "accuracySource"], in: range),
486	                measuredSampleCount: range["measured_sample_count"]?.intValue ?? range["measuredSampleCount"]?.intValue,
487	                isReady: range["ready"]?.boolValue
488	            ),
489	            charging: NinebotServerChargingPrediction(
490	                isCharging: charging["is_charging"]?.boolValue ?? charging["isCharging"]?.boolValue,
491	                remainingMinutes: firstDouble(["remaining_minutes", "remainingMinutes"], in: charging),
492	                estimatedFullAt: serverDateValue(charging["estimated_full_at"] ?? charging["estimatedFullAt"]),
493	                fastMinutesPerPercent: firstDouble(["fast_minutes_per_percent", "fastMinutesPerPercent"], in: charging),
494	                taperMinutesPerPercent: firstDouble(["taper_minutes_per_percent", "taperMinutesPerPercent"], in: charging),
495	                sampleCount: charging["sample_count"]?.intValue ?? charging["sampleCount"]?.intValue,
496	                accuracyPercent: firstDouble(["accuracy_percent", "accuracyPercent"], in: charging),
497	                confidencePercent: firstDouble(["confidence_percent", "confidencePercent"], in: charging),
498	                accuracySource: firstString(["accuracy_source", "accuracySource"], in: charging),
499	                measuredSampleCount: charging["measured_sample_count"]?.intValue ?? charging["measuredSampleCount"]?.intValue,
500	                isReady: charging["ready"]?.boolValue,
501	                estimatedSpeedKmh: firstDouble(["estimated_speed_kmh", "estimatedSpeedKmh"], in: charging)
502	            )
503	        )
504	    }
