506	    static func batteryChemistryInfo(from value: JSONValue?) -> NinebotBatteryChemistryInfo? {
507	        guard let object = value?.objectValue,
508	              let configuredRaw = firstString(["configured"], in: object),
509	              let configured = NinebotBatteryChemistry(rawValue: configuredRaw) else {
510	            return nil
511	        }
512	        return NinebotBatteryChemistryInfo(
513	            configured: configured,
514	            effective: firstString(["effective"], in: object) ?? "unknown",
515	            source: firstString(["source"], in: object) ?? "unresolved",
516	            nominalVoltage: firstDouble(["nominal_voltage", "nominalVoltage"], in: object),
517	            capacityWh: firstDouble(["capacity_wh", "capacityWh"], in: object),
518	            capacityAh: firstDouble(["capacity_ah", "capacityAh"], in: object)
519	        )
520	    }
