988	    static func monthStrings(from startDate: Date?, through endDate: Date) -> [String] {
989	        guard let startDate else {
990	            return [monthString(for: endDate)]
991	        }
992	
993	        var calendar = Calendar(identifier: .gregorian)
994	        calendar.timeZone = chinaTimeZone
995	        let startComponents = calendar.dateComponents([.year, .month], from: startDate)
996	        let endComponents = calendar.dateComponents([.year, .month], from: endDate)
997	        guard let start = calendar.date(from: startComponents),
998	              let end = calendar.date(from: endComponents),
999	              start <= end else {
1000	            return [monthString(for: endDate)]
1001	        }
1002	
1003	        var result: [String] = []
1004	        var cursor = start
1005	        while cursor <= end {
1006	            result.append(monthString(for: cursor))
1007	            guard let next = calendar.date(byAdding: .month, value: 1, to: cursor) else { break }
1008	            cursor = next
1009	        }
1010	        return result
1011	    }
