118	    private func firstRawDate(_ keys: [String]) -> Date? {
119	        guard let raw else { return nil }
120	        for key in keys {
121	            guard let value = raw[key] else { continue }
122	            if let date = Self.rawDateValue(value) {
123	                return date
124	            }
125	        }
126	        return nil
127	    }
