129	    private static func rawDateValue(_ value: JSONValue) -> Date? {
130	        if let number = value.doubleValue {
131	            return epochDateValue(number)
132	        }
133	
134	        guard let string = value.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines),
135	              !string.isEmpty else {
136	            return nil
137	        }
138	        if let number = Double(string) {
139	            return epochDateValue(number)
140	        }
141	        return nil
142	    }
143	
144	    private static func epochDateValue(_ number: Double) -> Date? {
145	        guard number > 0 else { return nil }
146	        let seconds = number > 1_000_000_000_000 ? number / 1000 : number
147	        let date = Date(timeIntervalSince1970: seconds)
148	        return date.timeIntervalSince1970 > 0 ? date : nil
149	    }
