1906	enum JSONValue: Codable, Equatable {
1907	    case object([String: JSONValue])
1908	    case array([JSONValue])
1909	    case string(String)
1910	    case number(Double)
1911	    case bool(Bool)
1912	    case null
1913	
1914	    init(from decoder: Decoder) throws {
1915	        if let container = try? decoder.container(keyedBy: DynamicCodingKey.self) {
1916	            var object: [String: JSONValue] = [:]
1917	            for key in container.allKeys {
1918	                object[key.stringValue] = try container.decode(JSONValue.self, forKey: key)
1919	            }
1920	            self = .object(object)
1921	            return
1922	        }
1923	
1924	        if var container = try? decoder.unkeyedContainer() {
1925	            var array: [JSONValue] = []
1926	            while !container.isAtEnd {
1927	                array.append(try container.decode(JSONValue.self))
1928	            }
1929	            self = .array(array)
1930	            return
1931	        }
1932	
1933	        let container = try decoder.singleValueContainer()
1934	        if container.decodeNil() {
1935	            self = .null
1936	        } else if let value = try? container.decode(Bool.self) {
1937	            self = .bool(value)
1938	        } else if let value = try? container.decode(Double.self) {
1939	            self = .number(value)
1940	        } else if let value = try? container.decode(String.self) {
1941	            self = .string(value)
1942	        } else {
1943	            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Unsupported JSON value")
1944	        }
1945	    }
1946	
1947	    func encode(to encoder: Encoder) throws {
1948	        switch self {
1949	        case .object(let object):
1950	            var container = encoder.container(keyedBy: DynamicCodingKey.self)
1951	            for (key, value) in object {
1952	                try container.encode(value, forKey: DynamicCodingKey(key))
1953	            }
1954	        case .array(let array):
1955	            var container = encoder.unkeyedContainer()
1956	            for value in array {
1957	                try container.encode(value)
1958	            }
1959	        case .string(let string):
1960	            var container = encoder.singleValueContainer()
1961	            try container.encode(string)
1962	        case .number(let number):
1963	            var container = encoder.singleValueContainer()
1964	            try container.encode(number)
1965	        case .bool(let bool):
1966	            var container = encoder.singleValueContainer()
1967	            try container.encode(bool)
1968	        case .null:
1969	            var container = encoder.singleValueContainer()
1970	            try container.encodeNil()
1971	        }
1972	    }
1973	
1974	    var objectValue: [String: JSONValue]? {
1975	        guard case .object(let object) = self else { return nil }
1976	        return object
1977	    }
1978	
1979	    var arrayValue: [JSONValue]? {
1980	        guard case .array(let array) = self else { return nil }
1981	        return array
1982	    }
1983	
1984	    var stringValue: String? {
1985	        switch self {
1986	        case .string(let string):
1987	            return string
1988	        case .number(let number):
1989	            if number.rounded() == number {
1990	                return String(Int(number))
1991	            }
1992	            return String(number)
1993	        case .bool(let bool):
1994	            return bool ? "true" : "false"
1995	        default:
1996	            return nil
1997	        }
1998	    }
1999	
2000	    var doubleValue: Double? {
2001	        switch self {
2002	        case .number(let number):
2003	            return number
2004	        case .string(let string):
2005	            return Double(string)
2006	        case .bool(let bool):
2007	            return bool ? 1 : 0
2008	        default:
2009	            return nil
2010	        }
2011	    }
2012	
2013	    var intValue: Int? {
2014	        guard let doubleValue else { return nil }
2015	        return Int(doubleValue)
2016	    }
2017	
2018	    var boolValue: Bool? {
2019	        switch self {
2020	        case .bool(let bool):
2021	            return bool
2022	        case .number(let number):
2023	            return number != 0
2024	        case .string(let string):
2025	            let normalized = string.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
2026	            if ["1", "true", "yes", "on"].contains(normalized) { return true }
2027	            if ["0", "false", "no", "off"].contains(normalized) { return false }
2028	            return nil
2029	        default:
2030	            return nil
2031	        }
2032	    }
2033	
2034	    subscript(key: String) -> JSONValue? {
2035	        objectValue?[key]
2036	    }
