10	final class ServerClientStubURLProtocol: URLProtocol {
11	    struct Reply {
12	        var statusCode: Int
13	        var body: Data
14	
15	        init(statusCode: Int = 200, body: Data = Data()) {
16	            self.statusCode = statusCode
17	            self.body = body
18	        }
19	
20	        static func json(_ text: String, statusCode: Int = 200) -> Reply {
21	            Reply(statusCode: statusCode, body: Data(text.utf8))
22	        }
23	
24	        static func text(_ text: String, statusCode: Int = 200) -> Reply {
25	            Reply(statusCode: statusCode, body: Data(text.utf8))
26	        }
27	
28	        static func empty(statusCode: Int = 200) -> Reply {
29	            Reply(statusCode: statusCode, body: Data())
30	        }
31	    }
