33	    private static let lock = NSLock()
34	    private static var storedHandler: ((URLRequest) -> Reply)?
35	    private static var recorded: [URLRequest] = []
36	
37	    static func install(_ handler: @escaping (URLRequest) -> Reply) {
38	        lock.lock()
39	        storedHandler = handler
40	        recorded = []
41	        lock.unlock()
42	    }
43	
44	    static func reset() {
45	        lock.lock()
46	        storedHandler = nil
47	        recorded = []
